1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResults = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
24	
25	const BASE_PREMIUMS: Record<string, number> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	  potion: 40,
30	  rune: 25,
31	  moonstone: 25,
32	};
33	
34	const BLOCK_SIZE = 3;
35	const BLOCK_BASE_PREMIUM = 60;
36	
37	const COMPONENT_TYPES = ["rune", "moonstone"];
38	
39	/** Items are priced per type, because the component block applies to alike items. */
40	const groupByType = (items: Item[]): Map<string, Item[]> =>
41	  items.reduce(
42	    (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
43	    new Map<string, Item[]>(),
44	  );
45	
46	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
47	
48	/**
49	 * Item-level risk surcharges, each a rate on the item's own base premium.
50	 * They are separate addends: unlike the policy-level initial assessment, they
51	 * do not compound with each other or with it.
52	 */
53	const CURSE_SURCHARGE = 0.5;
54	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
55	const HIGH_ENCHANTMENT_LEVEL = 5;
56	
57	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; rate: number }[] = [
58	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
59	  {
60	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
61	    rate: HIGH_ENCHANTMENT_SURCHARGE,
62	  },
63	];
64	
65	const itemSurcharges = (item: Item): number =>
66	  ITEM_SURCHARGE_RULES.filter(({ applies }) => applies(item)).reduce(
67	    (sum, { rate }) => sum + itemBasePremium(item) * rate,
68	    0,
69	  );
70	
71	/**
72	 * A building block of exactly 3 alike components is offered at a special base
73	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
74	 * runes are charged per item.
75	 */
76	const formsComponentBlock = (type: string, items: Item[]): boolean =>
77	  COMPONENT_TYPES.includes(type) && items.length === BLOCK_SIZE;
78	
79	const alikeItemsBasePremium = (type: string, items: Item[]): number =>
80	  formsComponentBlock(type, items)
81	    ? BLOCK_BASE_PREMIUM
82	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
83	
84	const policyBasePremium = (items: Item[]): number =>
85	  [...groupByType(items)].reduce(
86	    (sum, [type, alikeItems]) => sum + alikeItemsBasePremium(type, alikeItems),
87	    0,
88	  );
89	
90	/** Premiums are rounded in the MHPCO's favour, i.e. up. */
91	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
92	
93	/**
94	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
95	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
96	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
97	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
98	 */
99	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
100	
101	const policyItemSurcharges = (items: Item[]): number =>
102	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
103	
104	const quote = (step: QuoteStep): { premium: number } => {
105	  const assessedPremium = withSurcharge(
106	    policyBasePremium(step.items),
107	    INITIAL_ASSESSMENT_SURCHARGE,
108	  );
109	
110	  return {
111	    premium: roundInMHPCOsFavour(
112	      assessedPremium + policyItemSurcharges(step.items) + PROCESSING_FEE,
113	    ),
114	  };
115	};
116	
117	export const runScenario = (scenario: Scenario): ScenarioResults => ({
118	  results: scenario.steps.map(quote),
119	});
